tags.gen_ai.tool.call.result:
[
  {
    "itemId": "ARCH-01",
    "text": "Die Lösung ist als digitale App zur Verbesserung bzw. Förderung der Kommunikation zwischen betreuten Menschen mit Beeinträchtigungen und anderen Personen angestrebt; die konkrete Ausgestaltung ist noch nicht vollständig konkretisiert.",
    "rationale": "Beschreibt den übergeordneten Lösungsrahmen und die angestrebte Form als digitale App, ohne ein konkretes aktuelles Umsetzungs-Constraint für einzelne PBIs vorzugeben. Daher vor allem als architektonische Leitentscheidung zu dokumentieren.",
    "sourceClaimIds": [
      "canon-produktziel-kommunikation-verbessern"
    ]
  },
  {
    "itemId": "ARCH-03",
    "text": "Als Kernansatz soll die App Wissen über Profil und Kommunikationsweise einer Person bereitstellen, damit Nutzer bei Verständnisschwierigkeiten nachsehen können; die konkrete Ausprägung dieses Ansatzes ist noch weiter auszuarbeiten.",
    "rationale": "Der Kernansatz, Profil- und Kommunikationswissen nachschlagbar bereitzustellen, ist eine tragende Lösungsentscheidung und begrenzt zugleich die fachliche Ausgestaltung der Kernfunktionen rund um Profile und Kommunikationswissen.",
    "sourceClaimIds": [
      "canon-app-profilwissen-kommunikationshilfe"
    ]
  },
  {
    "itemId": "ARCH-06",
    "text": "Es muss berücksichtigt werden, dass vorhandene Akten im Arbeitsalltag schwer nutzbar sein können, weil sie umfangreich sind und gesuchte Informationen nicht schnell gefunden werden; dies ist jedoch nur als persönliche Einschätzung belegt.",
    "rationale": "Die Aussage beschreibt ein belegtes Nutzungsrisiko beziehungsweise eine Problemwahrnehmung über bestehende Akten. Sie ist eher Kontextwissen für die Architekturbegründung als ein harter Rahmen für konkrete aktive PBIs.",
    "sourceClaimIds": [
      "canon-risiko-akten-schwer-nutzbar"
    ]
  },
  {
    "itemId": "ARCH-07",
    "text": "Die App darf keine Selbstregistrierung erlauben; Zugang erfolgt nur per Login mit intern vergebenen Accounts.",
    "rationale": "Login nur mit intern vergebenen Accounts und ohne Selbstregistrierung ist eine klare Sicherheits- und Zugangsentscheidung. Sie begrenzt die Umsetzung von Account- und Login-Funktionen unmittelbar.",
    "sourceClaimIds": [
      "canon-login-ohne-selbstregistrierung"
    ]
  },
  {
    "itemId": "ARCH-08",
    "text": "Es muss mindestens die Rollen Admin und User geben; Admins verwalten Accounts und Rechte, User können Inhalte hinzufügen, aber nichts löschen.",
    "rationale": "Die Mindestrollen Admin und User sowie die Löschbeschränkung für User sind konkrete Entscheidungen zum Basisrechtemodell. Diese Rahmenbedingungen wirken direkt auf Account- und Rechtefunktionen.",
    "sourceClaimIds": [
      "canon-rollen-admin-user"
    ]
  },
  {
    "itemId": "ARCH-10",
    "text": "Zusätzlich soll es einen Bewohner-Account geben, der nur das eigene Profil sehen darf und nur eingeschränkte Funktionen nutzen kann, insbesondere Zugriff auf About Me und gegebenenfalls das Hinzufügen eigener Bilder.",
    "rationale": "Der Bewohner-Account mit ausschließlich eigenem Profilzugriff und eingeschränkten Funktionen ist eine konkrete Zugriffs- und Rollenentscheidung. Diese beeinflusst das Rechtemodell direkt.",
    "sourceClaimIds": [
      "canon-bewohner-account-mit-beschraenkung"
    ]
  },
  {
    "itemId": "ARCH-11",
    "text": "Mitarbeiter dürfen nicht einrichtungsübergreifend auf alle Profile zugreifen, sondern nur auf Profile der Einrichtung, in der sie tätig sind; die technische Umsetzung dieser Beschränkung ist noch zu erarbeiten.",
    "rationale": "Die Beschränkung auf Profile der eigenen Einrichtung ist eine wesentliche Mandanten- und Zugriffsentscheidung. Sie setzt klare Grenzen für Rechte- und Zugriffsumsetzung.",
    "sourceClaimIds": [
      "canon-zugriff-nach-einrichtung-beschraenkt"
    ]
  },
  {
    "itemId": "ARCH-12",
    "text": "Die konkrete Ausgestaltung der Rechteverwaltung ist noch nicht festgelegt und muss später entschieden werden.",
    "rationale": "Die Aussage hält fest, dass die Rechteverwaltung noch nicht entschieden ist. Das ist derzeit vor allem dokumentationswürdiger Architekturstatus, aber noch keine konkrete technische Arbeit und kein belastbarer Rahmen für andere PBIs.",
    "sourceClaimIds": [
      "canon-rechteverwaltung-noch-offen"
    ]
  },
  {
    "itemId": "ARCH-13",
    "text": "Für die Rechte- und Accountverwaltung soll ein separater Admin-Bildschirm erwogen werden, auf dem nur Admins Accounts anlegen und Rollen vergeben können.",
    "rationale": "Ein separater Admin-Bildschirm ist als Lösungsoption beschrieben, die Architektur und Bedienmodell der Administration betrifft. Wegen der Formulierung als erwogene Option ist dies derzeit primär eine dokumentierbare Designrichtung.",
    "sourceClaimIds": [
      "canon-admin-screen-pruefen"
    ]
  },
  {
    "itemId": "ARCH-24",
    "text": "Auf Kommunikationsseiten soll eine Suchfunktion vorhanden sein; dafür muss ein standardisiertes Beschreibungsmuster für Kommunikationseinträge definiert werden, damit Suche und spätere Filterung funktionieren.",
    "rationale": "Das erforderliche standardisierte Beschreibungsmuster ist eine fachlich-technische Strukturentscheidung, damit Suche und spätere Filterung funktionieren. Das begrenzt die Such- und Erfassungslogik direkt.",
    "sourceClaimIds": [
      "canon-suche-kommunikation-und-beschreibungsmuster"
    ]
  },
  {
    "itemId": "ARCH-31",
    "text": "Bei der Gestaltung soll auf Barrierefreiheit geachtet werden, insbesondere große Schrift, ausreichender Kontrast und zurückhaltender Farbeinsatz.",
    "rationale": "Barrierefreiheit mit großer Schrift, Kontrast und zurückhaltendem Farbeinsatz ist eine Querschnittsentscheidung für die UI-Gestaltung und begrenzt die Umsetzung der mobilen Nutzung.",
    "sourceClaimIds": [
      "canon-barrierefreiheit-beruecksichtigen"
    ]
  },
  {
    "itemId": "ARCH-36",
    "text": "Die App soll plattformübergreifend auf iPhone und Android laufen.",
    "rationale": "Die plattformübergreifende Nutzung auf iPhone und Android ist eine grundlegende Architekturentscheidung und begrenzt die technische Umsetzung der mobilen App.",
    "sourceClaimIds": [
      "canon-plattform-ios-android"
    ]
  },
  {
    "itemId": "ARCH-37",
    "text": "Für die Entwicklung soll Flutter mit Dart verwendet werden, um die plattformübergreifende Umsetzung zu unterstützen.",
    "rationale": "Flutter mit Dart ist eine konkrete Technologieentscheidung. Sie ist klassisch sowohl Design als auch Rahmenbedingung für den Technologiestack und die mobile Umsetzung.",
    "sourceClaimIds": [
      "canon-technologiestack-flutter-dart"
    ]
  },
  {
    "itemId": "ARCH-38",
    "text": "Das Paket GetX soll als technische Option berücksichtigt und in der Umsetzung erprobt werden.",
    "rationale": "GetX ist als technische Option zur Erprobung beschrieben, also vor allem eine dokumentierbare Architektur- beziehungsweise Stack-Option. Ohne bereits festgelegten Zwang ist dies noch kein Constraint.",
    "sourceClaimIds": [
      "canon-getx-pruefen"
    ]
  },
  {
    "itemId": "ARCH-39",
    "text": "Firebase Firestore ist als Datenbanklösung vorläufig vorgesehen, jedoch noch nicht endgültig festgelegt.",
    "rationale": "Firestore ist vorläufig vorgesehen und damit eine vorläufige Technologieentscheidung. Wegen der explizit fehlenden Endgültigkeit ist dies derzeit eher Design-Status als harter Rahmen für andere PBIs.",
    "sourceClaimIds": [
      "canon-firebase-firestore-vorlaeufig"
    ]
  },
  {
    "itemId": "ARCH-40",
    "text": "Es muss geklärt werden, ob und wie Cloud-Daten lokal auf dem Gerät gespeichert oder gecacht werden sollen. [canon-lokaler-cache-klären]",
    "rationale": "Der lokale Cache ist ausdrücklich noch zu klären. Das ist momentan offener Architekturpunkt und damit dokumentationswürdiges Design-Wissen, aber keine unmittelbar ableitbare technische Arbeit.",
    "sourceClaimIds": []
  },
  {
    "itemId": "ARCH-45",
    "text": "Das Produktziel ist zusätzlich dadurch gerahmt, dass Kommunikation im Alltag zentral ist und das Projekt als Weiterentwicklungsmöglichkeit gesehen wird.",
    "rationale": "Die Aussage rahmt das Produktziel allgemein und beschreibt strategischen Kontext, aber keine konkrete Einschränkung einzelner aktiver PBIs. Daher vor allem als architektonischer Kontext zu dokumentieren.",
    "sourceClaimIds": [
      "ADJ-GAP-AU-0003"
    ]
  }
]

